insert into org.gate (codigo, nome, entra, quem_fornece, criterio_saida, desbloqueia) select codigo, nome, entra, quem_fornece, criterio_saida, desbloqueia from jsonb_to_recordset($j$[{"codigo": "G1", "nome": "Empresas", "entra": "Lista das empresas do portfólio. Para cada uma: regime tributário, porte e se é agente de pequeno porte para a ANPD.", "quem_fornece": "Você", "criterio_saida": "Cada empresa cadastrada com regime e porte", "desbloqueia": "G4, G5, rateio (GE-06), prazos em dobro da ANPD (GO-09)"}, {"codigo": "G2", "nome": "Pessoas por papel", "entra": "Sócios do Ecossistema e de cada empresa, executivo de cada empresa, líder de cada círculo (você na Identidade) e encarregado de dados de cada empresa. O Administrador do IMTS.OS é você (decidido em 03/10/2026)", "quem_fornece": "Você e os sócios", "criterio_saida": "Nenhum papel do modelo sem pessoa; ninguém acumula papéis que se fiscalizam, como lançar e aprovar o mesmo pagamento", "desbloqueia": "G3, G7 e todas as alçadas com nome"}, {"codigo": "G6", "nome": "Ratificação dos sócios", "entra": "Os sócios ratificam o que você aprovou: método de estratégia, regras gerais de contrato, alçadas, tabela matéria × órgão, critério dos agentes (ID-02) e apetite a risco", "quem_fornece": "Sócios", "criterio_saida": "Ata assinada (GO-02)", "desbloqueia": "Valor formal das regras; libera o G3"}, {"codigo": "G3", "nome": "Valores do primeiro ciclo", "entra": "Orçamento de cada empresa e círculo, reserva de apostas, limite de cada unidade, reserva de contingência e preço-base de cada oferta", "quem_fornece": "Estratégia e Gestão, com aprovação dos sócios (ES-02 e ES-03 do primeiro ciclo)", "criterio_saida": "Alocação e alvos aprovados pelos sócios", "desbloqueia": "As alçadas que usam essas referências"}, {"codigo": "G4", "nome": "Regra fiscal e folha", "entra": "Tributos, obrigações acessórias e calendário de cada empresa pelo regime; convenção coletiva aplicável", "quem_fornece": "Assessoria contábil e trabalhista", "criterio_saida": "Calendário fiscal e de folha de cada empresa conferido pela assessoria", "desbloqueia": "GE-05, GE-13"}, {"codigo": "G5", "nome": "Fontes no texto oficial", "entra": "Cumprido em 03/10/2026 na Lei 14.133, no Código Civil, na CLT e na Lei 8.036: todos os artigos citados conferidos no Planalto, com o link oficial na aba Fontes. Falta só a Resolução CD/ANPD nº 15/2024: o Diário Oficial não abriu nas ferramentas de leitura", "quem_fornece": "Assessoria jurídica, ou eu, com o link do Diário Oficial", "criterio_saida": "Arts. 6º e 9º da Resolução CD/ANPD nº 15/2024 e a regra do prazo em dobro conferidos no oficial", "desbloqueia": "Uso do prazo de incidente em peça, contrato e política"}, {"codigo": "G7", "nome": "Motor e sistemas", "entra": "Escolher o motor que executa os fluxos e ligar cada tarefa a um sistema. Construir os agentes e as automações e liberá-los pela IT-06", "quem_fornece": "Integração, com você", "criterio_saida": "Cada tarefa de agente ou automação tem sistema e teste aprovado; cada agente foi liberado pela IT-06", "desbloqueia": "Execução real das 73 jornadas"}, {"codigo": "G8", "nome": "Modelos e políticas redigidos", "entra": "Textos finais dos modelos de contrato e das políticas, a partir dos rascunhos aprovados", "quem_fornece": "Governança e Gestão, com a assessoria jurídica", "criterio_saida": "Cada texto aprovado por quem decide, pela aba Parâmetros em aberto", "desbloqueia": "Uso em cliente, fornecedor e pessoa"}, {"codigo": "G9", "nome": "Calibração", "entra": "Depois de dois ciclos: medir tempo, volume e carga; rever frações, cadências e níveis de automação", "quem_fornece": "Inteligência (IN-04) e Integração (IT-08)", "criterio_saida": "Parâmetros revistos com dados e aprovados por quem decide", "desbloqueia": "Versão 2 do modelo"}]$j$::jsonb) as x(codigo text, nome text, entra text, quem_fornece text, criterio_saida text, desbloqueia text);
